class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def partitionList(nums, x):
    head = build(nums)
    small_head = ListNode()
    big_head = ListNode()
    small, big = small_head, big_head
    while head:
        if head.val < x:
            small.next = head
            small = head
        else:
            big.next = head
            big = head
        head = head.next
    big.next = None
    small.next = big_head.next
    return dump(small_head.next)
